def generate_real_ofac_csv(output_path: Path = DATA_DIR / "ofac.csv") -> Path:
    lines = [line.strip() for line in OFAC_REAL_DATA.strip().split("\n") if line.strip()]
    with open(output_path, "w", newline="", encoding="utf-8") as f:
        for line in lines:
            f.write(line + "\n")
    print(f"[OK] Wrote real OFAC energy dataset: {output_path} ({len(lines)-1} entities/vessels)")
    return output_path

if __name__ == "__main__":
    generate_real_ofac_csv()
